{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 민간단체 회원인 보호자가 공고 후 10일 경과 시 유기견을 우선 입양할 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "공고한 날부터 10일이 지나도 소유자가 나타나지 않은 경우, 구청장 또는 동물보호센터의 장은 보호조치하고 있는 자에게 우선 입양 또는 기증할 수 있다. 질문의 보호자는 구청장이 조례에 따라 구조한 유기견을 보호조치하고 있는 자에 해당하므로, 이 요건에 맞으면 우선 입양 대상이 될 수 있다.",
          "b_ids": "동물보호:제10조제4항, 동물보호:제10조제3항단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
